def sanitize_address(addr, encoding):
    """
    Format a pair of (name, address) or an email address string.
    """
    if isinstance(addr, tuple):
        nm, addr = addr
    else:
        nm = None
    addr = str(addr)
    try:
        mailbox, rest = parser.get_mailbox(addr)
    except (HeaderParseError, IndexError):
        raise ValueError('Invalid address "%s"' % addr)
    if rest:
        raise ValueError('Invalid address; only %s could be parsed from "%s"' % (mailbox, addr))
    if nm is None:
        nm = mailbox.display_name or ''
    localpart = mailbox.local_part or ''
    domain = mailbox.domain or ''
    if any('\n' in part or '\r' in part for part in (addr, nm, localpart, domain)):
        raise ValueError('Invalid address; address parts cannot contain newlines.')

    nm = Header(nm, encoding).encode()
    # Encode the local part only when it contains non-ASCII characters.
    try:
        localpart.encode('ascii')
    except UnicodeEncodeError:
        localpart = Header(localpart, encoding).encode()
    domain = domain.encode('idna').decode('ascii')

    # An `email.headerregistry.Address` object is used since
    # email.utils.formataddr() naively encodes the name as ascii (see #25986).
    return str(Address(nm, username=localpart, domain=domain))

