def test_sanitize_address_newlines(self):
    for newline in ('\r', '\n', '\r\n'):
        for address in (
            'Name%s <to@example.com>' % newline,
            '"to%sname"@example.com' % newline,
            'to@exam%sple.com' % newline,
            ('Name%s' % newline, 'to@example.com'),
            ('Name', '"to%sname"@example.com' % newline),
        ):
            with self.subTest(address=address):
                with self.assertRaises(ValueError):
                    sanitize_address(address, 'utf-8')
    # The mailbox parser can reveal newlines in encoded display names.
    for encoded_newline in ('=0D', '=0A', '=0D=0A'):
        address = '=?utf-8?q?Name%s?= <to@example.com>' % encoded_newline
        with self.subTest(address=address):
            with self.assertRaises(ValueError):
                sanitize_address(address, 'utf-8')

